from math import gcd
from functools import reduce
from itertools import accumulate

def lcm(a, b):
    return a * b // gcd(a, b)

def solve(N, sets):
    MOD = 998244353
    factorials = [1]
    last_lcm = 1
    for i in accumulate(sets, lcm):
        factorials.append(i * factorials[-1] % MOD)
        last_lcm = i

    dp = [1] * N
    for i in range(N):
        if i + 1 < N:
            dp[i] = (dp[i] * (i + 1) % MOD * factorials[last_lcm - i]) % MOD
        if i > 0:
            dp[i] = (dp[i] * (N - i) % MOD * factorials[last_lcm - i]) % MOD
    return dp[N-1]

