def lexicographically_smallest(S, K):
    # Count frequency of each character
    freq = {}
    for char in S:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Priority queue to find lexicographically smallest
    pq = [(freq[char], char) for char in freq.keys()]
    if K <= len(pq):
        return ''.join([char * count for count, char in pq[:K]])
    else:
        pq.sort(key=lambda x: (x[1], -x[0]))
        pq[:K] += [(0, 'z')] * (len(pq) - K)
        result = []
        for _, char in pq:
            result.append(char)
        return ''.join(result)

