def find_longest_good_path(cities, n, k, cities_used):
    long_path, good_paths = [], []
    heap = []
    heapq.heappush(heap, (0, [1, 1]))
    while heap:
        dist, path = heapq.heappop(heap)
        if len(path) < n:
            if path:
                city = path[-1]
                good_path = path[::-1]
                long_path.append((city, good_path))
                if len(good_path) == k + 1:
                    long_path += good_path[1:]
                    good_paths += long_path.copy()
                    return good_paths
            for i in range(1, len(path)):
                need = k + 1 - len(path[i:])
                if need > (n - len(path[:i])):
                    continue
                neighbors = cities[path[i]]
                need -= len(neighbors & ((set(path[:i]) | set(path[:i]) - set(path[i:]))))
                tower = len(path[i:])
                not_tower = n - len(path)
                delta = tower - need - 1
                if partition := roll_need(neighbors, need, delta, tower, not_tower):
                    heapq.heappush(heap, (need + delta, path[:i] + partition))
                for j in range(min(need, tower)):
                    neighbor = neighbors[j // delta]
                    long_path += path[i:j // delta + 1] + [neighbor] + path[i + j % delta:][::-1]
                for vill_cities in cities[neighbor]:
                    if not vill_cities & cities_visited:
                        cities_used[i + j // delta][j % delta][-1] = []
                        cities_used[i + j // delta][j % delta].append(cities[j // delta][vill_cities])
                        cities_visited.clear()
                        cities_visited |= neighbor
                        break
