import heapq

def lexicographically_min_partition(N, K, S):
    # Create the triangular array for prefix sums
    prefix_sum = [[0] * (N + 1) for _ in range(K + 1)]
    for i in range(1, K + 1):
        for j in range(min(i + 1, N) + 1):
            prefix_sum[i][j] = i + (prefix_sum[i-1][j-1] if j > 1 else 0) + (prefix_sum[i-1][j] if j < N else 0)

    # Build the lex-min partition using binary search
    heap = [(0, 0, 0)]  # (prefix_sum with indices for partitioning, current character index, current partition index)
    lexicographic_min = [''] * K

    for k in range(N):
        non_empty_partitions = len(list(filter(lambda x: x > 0, heap)))
        if non_empty_partitions == K:
            lexicographic_min[K - 1] = min(heap, key=lambda x: (prefix_sum[K - 1][x[1] + 1] - x[0], x[1]))
            heap = [(prefix_sum[K - 1][0] + x[0], 0, 0)]  # Remove current character from heap
            for i in range(K):
                heapq.heappush(heap, (prefix_sum[K - 1][1] - prefix_sum[K - 1][0], 1, i))
        else:
            amount = n % (N - non_empty_partitions)
            index = non_empty_partitions - 1 + amount
            if index < K:
                heap = heapq.nsmallest(amount + 2, heap, key=lambda x: (prefix_sum[K - 1][x[1] + 1] - x[0], x[1]))
                lexicographic_min[index] = min(heap, key=lambda x: (prefix_sum[K - 1][x[1] + 1] - x[0], x[1]))
                if heap[0][1] == 1:
                    heapq.heappop(heap)
                elif heap[1][1] == 1:
                    heap[1], heap[0] = heap[0], heap[1]
                heap = [(prefix_sum[K - 1][0] + x[0], 0, 0)]  # Remove current character from heap
                for i in range(K):
                    heapq.heappush(heap, (prefix_sum[K - 1][1] - prefix_sum[K - 1][0], 1, i))

    return ''.join(lexicographic_min)

T = int(input())  # Number of test cases
