import sys

def add_shortcuts(n, k):
    shortcuts = []

    # Add shortcuts starting from each city and ensuring the shortest path is less than or equal to k
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if i > j:
                continue
            shortest_path = i
            current_length = 0
            visited = set()

            while i != j:
                shortest_path = min(shortest_path, i)
                if j in visited:
                    break
                visited.add(j)
                current_length += 1
                i = j
                j = shortest_path
                if current_length > k:
                    break

            if current_length <= k:
                shortcuts.append((i, j))

    # Ensure the graph remains a tree by removing the shortcuts
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) in shortcuts:
                shortcuts.remove((i, j))

    return len(shortcuts)

