import math

def d(n):
    """Return the number of divisors of n."""
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def calculate_sum(a, b, c):
    """Calculate the given sum and return the result modulo 2^30."""
    total_sum = 0
    for i in range(1, a + 1):
        for j in range(1, b + 1):
            for k in range(1, c + 1):
                total_sum += d(i * j * k)
    return total_sum % (1 << 30)

