from collections import defaultdict

def find_substring_indexes(s, t, pairs):
    n = len(s)
    m = len(t)
    pairs_by_char = defaultdict(list)

    # Map each letter in T to its pair in the alphabet
    for i, char in enumerate(t):
        if char in pairs:
            pairs_by_char[char].append(i)

    # Check if T can be formed from substring of S
    for i in range(n - m + 1):
        # Remove the current character from T
        t_without = ''.join(t[1:] if i == 0 else t[:len(t) - 1])
        for start in pairs_by_char.get(s[i]):
            for j in range(1, m + 1):
                # Try to match the remaining characters of T with the current pair set
                if all((t_without[start + j] == t[j] or t[j] in pairs.get(s[i + j], [])) for start in range(start, len(t), m)):
                    break
            else:
                continue
            break
        else:
            return [i]

    return []

def encode_pairs(pairs):
    return {char: pair for pairs_pair, char in pairs.items() for pair in pairs_pair}

def main(s, t):
    pairs = encode_pairs(pairs)
    return find_substring_indexes(s, t, pairs)

# Example usage
