import sys
from itertools import combinations_with_replacement

def construct_smallest_string(N, K, S):
    # Find the smallest starting index that ensures no trailing suffix
    smoke_index = -1
    for i in range(N):
        if all(ord(S[i+k]) < ord(S[i]) for k in range(1, N-i+1)):
            smoke_index = max(smoke_index, i)

    # Partition the string such that each part falls within the range
    # and then use the combinations_with_replacement to create the possible partitions
    partitioned_parts = []
    start = 0
    for i in range(K+1):
        end = start + i
        if S[start:end] in combinations_with_replacement(S, i):
            partitioned_parts.append(S[start:end])
            start = end

    return ''.join(partitioned_parts)

def solve(case_id, N, K, S):
    return construct_smallest_string(N, K, S)

