def calculate_time(n, L, walkways):
    time = 0
    energy = 0
    end_time = 0
    walkway_count = 0

    while True:
        if time >= L or energy < 0:
            break
        for i in range(walkway_count):
            x, y, speed = walkways[i]
            if x <= time:
                y_check = y
                if x < y:
                    y_check = min(y, x + speed * (L - time))
                time_limit = (y_check - x) / speed
                if time_limit <= 0 and speed > 0:
                    continue  # Walkway not hit yet
                elif time_limit < 0:
                    break
                time += time_limit + energy / speed
                energy = 1
                if time >= L:
                    return time
        if time < L:
            energy += 1
            walkway_count += 1

def solve(n, L, walkways):
    walkways.sort(key=lambda x: x[1])
    walkway_speeds = [w[2] for w in walkways]
