def calc_diameter(points):
    directions = {'+x': '>', '+y': 'v', '-x': '<', '-y': '^'}
    overall_directions = [directions.get(pair[1], '?') for pair in zip(points, points[1:])]

    max_max_distance = 0
    for i in range(1, len(overall_directions)):
        for j in range(i + 1, len(overall_directions)):
            last_got = 0
            speed = len(overall_directions)
            distance = 1
            is_plus_intersection = True

            for direction in overall_directions[i::speed]:
                if direction == '+x':
                    is_plus_intersection = True
                    last_got -= 1
                if direction == '+' and last_got <= 0:
                    last_got = 0
                if direction == '+y':
                    is_plus_intersection = True
                if direction == '-' and last_got > 0:
                    last_got += 1
                if direction == '-y':
                    is_plus_intersection = False

                    # Reduce distance, if a faster direction passed
                    while last_got > 0 and i + distance * speed < j:
                        last_got -= distance
                        distance += 2

                if is_plus_intersection:
                    continue

                overall_directions[j::speed] = [next_d for next_d in overall_directions[j::speed] if next_d != last_d and next_d != is_plus_intersection]
                distance *= 2
                max_max_distance = max(distance, max_max_distance)

    return max_max_distance**2

