from collections import Counter

def parse_input():
    n, m, d = map(int, input().split())
    sets = []
    for _ in range(m):
        size = int(input())
        set_ = list(map(int, input().split()))
        sets.append((size, set_))
    return n, m, d, sets

def subset_sum_less_than_k(sets, d, k):
    count = sum(1 for (size, _) in sets if size > k)
    if count <= k + 1:
        return count
    elif max(1, sets[-1][0] - sets[-2][0] - k) <= d:
        sets[-1][0] = (sets[-1][0] - sets[-2][0]) % d + d
        return count + (sets[-1][0] - (k + 1)) // sets[-1][0]

    return -1

def solve(n, m, d, sets):
    set_count = Counter()
    valid_sets = []
    for size, values in sets:
        set_count[size] += 1
        a = sorted([values[i] for i in range(size)])
        for i in range(len(a)):
            for j in range(i, len(a)):
                if set_count[i] + set_count[j] - min(i, j) * d >= 2:
                    if subset_sum_less_than_k(set_count.values(), d, max(set_count.values(), 1) + min(set_count.values(), 1)):
                        valid_sets.append((size, values))
                        break
                elif i == j and abs(a[i] - a[j]) < d:
                    break

    return min(len(valid_sets) or len(sets) - set_count.keys(), 2)

