    simple_cycles = defaultdict(set)
    for node in nodes:
        for adj_node in nodes[node]:
            for to_node, to_adj_node in enumerate(adj[node] + adj[adj_node], 1):
                cycle = [node]
                prev = -1
                stack = deque([(adj[adj_node].index(adj_node), to_node, to_adj_node)])
                while stack and prev != to_node:
                    prev = stack[0][1]
                    cycle.append(prev)
