from collections import deque

def encode_s(s):
    pairs = []
    for i in range(1, 26):
        for j in range(1, 26):
            a = chr(i + ord('a'))
            b = chr(j + ord('a'))
            pairs.append((a, b))
    queue = deque(s)
    encoded_s = ""
    while queue:
        letter = queue.popleft()
        if letter == ' ':
            if queue and queue[0] == letter:
                queue.popleft()
            continue
        for pair in pairs:
            if letter == pair[0]:
                prefix = pair[1]
                while queue and queue[0] == prefix:
                    queue.popleft()
                if queue:
                    encoded_s += queue.popleft()
                else:
                    encoded_s += letter
                break
        else:
            encoded_s += letter
    return encoded_s

def find_variant(s, t, start, end):
    first_half, second_half = s[start:end], s[start + len(t):]
    # Encode both halves
    encoded_first_half = encode_s(first_half)
    encoded_second_half = encode_s(second_half)
    return encoded_first_half.find(t) != -1 and encoded_second_half.find(t) != -1

def solve(s, t):
    start, end = 0, len(s)
    word = ''
    in_word = False
    count = 0

    while start < end and end < len(s):
        if s[end] == ' ':
            first_half = s[start:end]
            if in_word:
                count -= 1
                in_word = False
            if encode_s(first_half) == t:
                count += 1
            word += ' ' + first_half + ' '
            in_word = True
            start = end
            if count > 0:
                end = start + count
            else:
                end = start + len(t)
        else:
            end += 1

    if end < len(s):
        last_word = s[start:] if in_word else s[start:-1]
        if encode_s(last_word) == t:
            count += 1
    return count

def main():
    s_length, t_length = map(int, input().split())
    s = input()
    t = input()
    if not s_length >= t_length:
        return
    solutions = []
    while s_length + t_length:
        if solve(s, t) + 1:
            count = solve(s, t)
            if count:
                solutions.append(count)
            s = s[count + t_length - 1:]
        else:
            s_length -= 1
    for sol in solutions:
        print(sol, end=' ')

if __name__ == "__main__":
    main()
