def count_sequences(n, A):
    @lru_cache(maxsize=None)
    def dfs(index, last):
        if index == n:
            return 1
        num_choices = 0
        for i in range(len(A[index])):
            if A[index][i] != last:
                num_choices = (num_choices + dfs(index + 1, A[index][i])) % 998244353
        return num_choices

    return dfs(0, -1)

